// test-give-names.js
//
// /give finds the ingots, the leather strips and every ingredient.
//
// Patrick, 25 September: "Everytime I do /give Iron Ingot it says Nothing
// called that". /give named only what the other tables name, and the recipe
// table holds only recipes a profession owns, so Iron Ingot, Steel Ingot and
// Leather Strips (made by recipes nobody owns) and every ingredient were
// missing. ITEM_NAMES, generated by scripts/dev/Build-ItemNameTable.js out of
// game/data/recipes.json, fills that in.
//
// This runs the REAL buildThings, findIn and findThing out of
// game/gamemode.js, with the REAL RECIPES_BY_ID, ITEM_NAMES and ITEMS blocks,
// and checks the names people typed. It also runs the builder on a small
// recipes file in a temporary folder and checks what it writes.
//
// Read only. The builder runs on copies in a temporary folder.
const fs = require('fs');
const os = require('os');
const path = require('path');
const vm = require('vm');
const { spawnSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const GM = process.env.GM || path.join(ROOT, 'game', 'gamemode.js');
const src = fs.readFileSync(GM, 'utf8').split(String.fromCharCode(13)).join('');

let pass = 0, fail = 0;
function yes(what, cond) {
  if (cond) { pass++; console.log('PASS  ' + what); }
  else { fail++; console.log('FAIL  ' + what); }
}

function cut(from, to) {
  const a = src.indexOf(from);
  const b = src.indexOf(to, a);
  if (a < 0 || b < 0) { return null; }
  return src.slice(a, b + to.length);
}

// ------------------------------------------------------------------ A --
const recipes = cut('  var RECIPES_BY_ID = {', '\n  };');
const names = cut('  var ITEM_NAMES = {', '\n  };');
const admin = cut('  // ==== ADMIN_NAMES ====', '  // ==== end ADMIN_NAMES ====') || '';
const itemsLine = (src.match(/^const ITEMS = .*;$/m) || [null])[0];
const fns = cut('  function addThing(idx, name, desc) {', "\n  function buildBeasts() {");
const finder = cut('  function findIn(idx, want, kind) {', "return findIn(buildThings(), want, 'items'); }");
const finder2 = (function () {
  const a = src.indexOf('  function findIn(idx, want, kind) {');
  const b = src.indexOf('  function findBeast', a);
  return a >= 0 && b >= 0 ? src.slice(a, b) : null;
})();

yes('the ITEM_NAMES block is in gamemode.js', !!names);
yes('buildThings reads ITEM_NAMES', !!fns && fns.indexOf('ITEM_NAMES') !== -1);
yes('RECIPES_BY_ID, ITEMS, buildThings and findThing were found', !!recipes && !!itemsLine && !!fns && !!finder2);

if (names && recipes && itemsLine && fns && finder2) {
  const logged = [];
  const box = { log: function () { logged.push(Array.prototype.join.call(arguments, ' ')); } };
  vm.createContext(box);
  vm.runInContext(itemsLine.replace(/^const /, 'var ') + '\n' +
    'var ORES_BY_BASE = {}, HARVESTS_BY_BASE = {}, CROPS_BY_BASE = {}, FISH_BY_BASE = {}, HUNTS_BY_BASE = {};\n' +
    'var thingIndex = null;\n' + recipes + '\n' + names + '\n' + admin + '\n' +
    fns.replace(/\n  function buildBeasts\(\) \{$/, '') + '\n' + finder2, box);
  const give = function (w) { return box.findThing(String(w).toLowerCase()); };
  const cases = [
    ['Iron Ingot', 'Iron Ingot', '5ace4:Skyrim.esm'],
    ['iron ingot', 'Iron Ingot', '5ace4:Skyrim.esm'],
    ['Steel Ingot', 'Steel Ingot', '5ace5:Skyrim.esm'],
    ['Leather Strips', 'Leather Strips', '800e4:Skyrim.esm'],
    ['Leather', 'Leather', 'db5d2:Skyrim.esm'],
    ['Corundum Ingot', 'Corundum Ingot', '5ad93:Skyrim.esm'],
    ['iron ingots', 'Iron Ingot', '5ace4:Skyrim.esm'],
    ['firewood', null, '6f993:Skyrim.esm'],
  ];
  for (const c of cases) {
    const hit = give(c[0]);
    yes('/give ' + c[0] + ' finds ' + c[2], !!hit && hit.desc === c[2] && (!c[1] || hit.name === c[1]));
  }
  yes('the index built without an error: ' + (logged.join('; ') || 'nothing logged'), logged.length === 0);
  const miss = give('zzz not an item');
  yes('a name nobody has still says Nothing called that', !!miss && !miss.desc && /Nothing called that/.test(miss.why));
}

// ------------------------------------------------------------------ B --
const builder = path.join(ROOT, 'scripts', 'dev', 'Build-ItemNameTable.js');
yes('the builder is in scripts/dev', fs.existsSync(builder));
if (fs.existsSync(builder)) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'give-names-'));
  const rj = path.join(tmp, 'recipes.json');
  const gm = path.join(tmp, 'gamemode.js');
  fs.writeFileSync(rj, JSON.stringify({ recipes: {
    'a:Skyrim.esm': { name: 'Iron Ingot', out: '5ace4:Skyrim.esm', inputItems: [{ name: 'Iron Ore', item: '71cf3:Skyrim.esm' }] },
    'b:Mod.esp': { name: 'Iron Ingot', out: '800:Mod.esp', inputItems: [{ name: 'Iron  Ore ', item: '900:Mod.esp' }] },
    'c:Mod.esp': { name: 'Odd Thing', out: '801:Mod.esp', inputItems: [] }
  } }));
  fs.writeFileSync(gm, 'x\r\n  // ==== end RECIPES_BY_ID ====\r\ny\r\n');
  const run = function () { return spawnSync(process.execPath, [builder, '--recipes', rj, '--gamemode', gm], { encoding: 'utf8' }); };
  const r1 = run();
  const once = fs.readFileSync(gm, 'utf8');
  const r2 = run();
  const twice = fs.readFileSync(gm, 'utf8');
  yes('the builder runs', r1.status === 0 && r2.status === 0);
  yes('a second run changes nothing', once === twice);
  yes('a CRLF gamemode comes out LF (#3029)', once.indexOf('\r') < 0 && once.indexOf('\n') >= 0);
  yes('a shared name goes to Skyrim.esm', once.indexOf('"iron ingot": ["Iron Ingot", "5ace4:Skyrim.esm"]') !== -1);
  yes('ingredients are named, spaces tidied', once.indexOf('"iron ore": ["Iron Ore", "71cf3:Skyrim.esm"]') !== -1);
  yes('a mod-only name is kept', once.indexOf('"odd thing": ["Odd Thing", "801:Mod.esp"]') !== -1);
  try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (e) { }
}

console.log('');
console.log(pass + ' passed, ' + fail + ' failed');
process.exit(fail ? 1 : 0);
